R=V/'experiments/erdos-993-lower-region-compensation-dre-2026-09-25'
M=V/'experiments/erdos-993-master-ledger-2026-09-04'
p=M/'CLAIM-IDENTITY.json';raw=p.read_bytes();expected='197e7e10365430cb53d165056fb41b2341abb9e400ce3f73db3957ba77ddb170'
assert hashlib.sha256(raw).hexdigest()==expected,'Concurrent registry change; reconcile before continuing'
assert (R/'cycles/cycle-4/CONTROLLER-CLOSEOUT.md').is_file()
d=json.loads(raw);prior=json.loads(raw)['claims'];assert len(prior)==426
new=json.loads('[{"claim_key": "E993-LOWER-REGION-C4-T4-SIGNED-CROSS-TAG-INJECTIVITY", "statement": "For every finite ordinary tree T and natural p with x(T)+2<=p and 3p<2alpha(T)+1, let F be the original leaves v with Delta_p(T-v)<0. Over Q, let K_j have basis pairs (v,A) with v in F and A an independent j-set of H_v=T-{v,s_v} meeting W_v=N_T(s_v) minus {v}. Fix total orders on vertices and F. The linear map L:K_p -> K_(p-1) deletes each u in increasing position from A with coefficient (-1)^(position(u,A)-1); for B=A minus {u}, it retains v if (v,B) is a destination basis pair, otherwise uses the least w in F for which (w,B) is a destination basis pair, and omits the term if no such w exists. Then L is injective.", "scope": "The exact C4-T4 signed face-only, least-eligible-favorable-tag retagging map on rational tagged relative-face spaces, with the fixed strict original-leaf selector and original supports. Refuted by T=K_(1,12), p=8, ordered vertices 0<1<...<12 and ordered tags 1<...<12: the nine-term boundary of C={2,...,10} at tag 1 is nonzero and maps to zero. The same vector uses only retained-tag branches, so changing the tag order does not repair it. No assertion about another map, unsigned local deletion, Hall, or the scalar aggregate.", "status": "REFUTED", "evidence_grade": "exact_finite_refutation", "formal_award": false, "novelty_claimed": false, "known_witness_order": 13, "witness_minimality": "Not asserted or tested", "aliases": [], "alias_patterns": [], "certificate": "experiments/erdos-993-lower-region-compensation-dre-2026-09-25/preparation/C4-PREP-FINAL-FENCE-IDENTITIES/REPORT.md and EVIDENCE.json; independent exact replay. Complete selected sum negative. Cycle4 controller closeout; no formal award.", "terminal_history": [{"run": "erdos-993-lower-region-compensation-dre-2026-09-25", "cycle": 4, "date": "2026-09-26", "event": "Exact mechanism refutation, independently audited; main aggregate untouched."}]}, {"claim_key": "E993-LOWER-REGION-LOCAL-MARKED-ADDABILITY-NONPOSITIVE-COVARIANCE", "statement": "For every finite ordinary tree T and natural p with x(T)+2<=p and 3p<2alpha(T)+1, and every original leaf v in the fixed strict selector F={v: Delta_p(T-v)<0}, put k=p-1, H_v=T-{v,s_v}, and W_v=N_T(s_v) minus {v}. If i_k(H_v)>0, take A uniformly from the independent k-sets of H_v, let M_v(A)=1 if A meets W_v and 0 otherwise, and let e_v(A) be the number of actual vertices of H_v addable to A. Then Cov(M_v,e_v)<=0.", "scope": "Local, single-selected-leaf rank-k covariance under the uniform independent-k-set measure in H_v; actual addability is counted in H_v. Refuted on the specified labeled order-24 tree at p=10, k=9, selected leaf v=0, with Cov=1773113/13677^2>0. This does not assert a positive full favorable-leaf sum, a universal positive covariance, or failure of the early-rank occupancy transfer CT_x.", "status": "REFUTED", "evidence_grade": "exact_finite_refutation", "formal_award": false, "novelty_claimed": false, "known_witness_order": 24, "witness_minimality": "Not asserted or tested", "aliases": [], "alias_patterns": [], "certificate": "experiments/erdos-993-lower-region-compensation-dre-2026-09-25/preparation/C4-PREP-FINAL-FENCE-IDENTITIES/REPORT.md and EVIDENCE.json; independent exact replay. Complete selected sum negative. Cycle4 controller closeout; no formal award.", "terminal_history": [{"run": "erdos-993-lower-region-compensation-dre-2026-09-25", "cycle": 4, "date": "2026-09-26", "event": "Exact mechanism refutation, independently audited; main aggregate untouched."}]}]')
assert len(new)==2 and not ({c['claim_key']for c in prior}&{c['claim_key']for c in new})
d['claims'].extend(new);d['last_updated']='2026-09-26';d['update_note']=d.get('update_note','')+'; Cycle4 closed18/36/3/1; two independently replayed exact mechanism refutations, no new formal award; T_m candidate held OPEN for Cycle5.'
assert d['claims'][:426]==prior
out=(json.dumps(d,indent=2,ensure_ascii=False)+'\n').encode()
ident=R/'control/C5-REGISTERED-CLAIM-IDENTITY.json';ledger=R/'ledgers/C5-OBLIGATIONS.csv';assert not ident.exists() and not ledger.exists()
ident.write_bytes(out)
with ledger.open('x',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['claim_id','status','registered_statement','registered_scope','evidence_grade']);w.writeheader()
 for c in d['claims']:w.writerow({'claim_id':c['claim_key'],'status':c['status'],'registered_statement':c['statement'],'registered_scope':c['scope'],'evidence_grade':c.get('evidence_grade','see_certificate')})
q=subprocess.run([sys.executable,str(V/'skills/mathematical-solver-dre-controller/scripts/lint_claim_status.py'),'--identity',str(ident),'--ledger',str(ledger),'--json'],capture_output=True,text=True)
(R/'receipts/C4-FINAL-REGISTRATION-LINT.json').write_text(q.stdout);assert q.returncode==0,q.stdout+q.stderr
lp=M/'LEDGER.md';old=lp.read_text();start=old.index('**Current orientation,');end=old.index('\n\n',start)
para='**Current orientation, 2026-09-26.** The registry has428 identities (255 VERIFIED,96 REFUTED,26 CONDITIONAL,51 OPEN), at mixed evidence grades. Lower-region Cycles1 through4 are complete, each18 searches/36 critics/3 adjudicators/1 synthesis. Four narrow keys retain their formal order-band/first-shell awards. Cycle4 adds exact refutations of the specified signed retagging operator and local marked/addability nonpositive covariance; both witnesses have negative complete aggregates. The all-m ordinary T_m candidate passed independent computer-assisted preparation review but remains OPEN for Cycle5 adversarial review, without Lean certification. Full ordinary lower-region aggregate, weighted two-for-one Hall, governed beta aggregate and Erdos993 remain OPEN. Code r29, census M(6)=22 and K1 closure x<=6 are preserved at their exact grades. Cycles5 and6 and final documentation/publication remain pending. Historical sections retain dated scopes and counts.'
updated=old[:start]+para+old[end:]
updated+='\n\n## Lower-region Cycle4 closeout, 2026-09-26\n\nAll18/36/3/1 seats completed. Two new exact finite mechanism refutations were independently reviewed and replayed; all426 prior claim objects are unchanged. See experiments/erdos-993-lower-region-compensation-dre-2026-09-25/cycles/cycle-4/CONTROLLER-CLOSEOUT.md and preparation/C4-PREP-FINAL-FENCE-IDENTITIES/REPORT.md. Mathematical corrections and the AF return identity permutation remain append-only and are resolved in the selfcontained synthesis. No universal target or new formal award follows. T_m uniform candidate remains OPEN pending Cycle5.\n'
for rel,content in [('inputs/C4-FINAL-MASTER-BEFORE.json',raw),('inputs/C4-FINAL-LEDGER-BEFORE.md',old.encode())]:
 dest=R/rel;assert not dest.exists();dest.write_bytes(content)
assert p.read_bytes()==raw and lp.read_text()==old,'Concurrent master change'
p.write_bytes(out);lp.write_text(updated)
counts={s:sum(c['status']==s for c in d['claims'])for s in ['VERIFIED','REFUTED','CONDITIONAL','OPEN']}
receipt={'previous_count':426,'current_count':428,'counts':counts,'before_sha256':expected,'after_sha256':hashlib.sha256(out).hexdigest(),'unchanged_prior_claim_objects':426,'new_keys':[c['claim_key']for c in new],'formal_awards':[]}
(R/'receipts/C4-FINAL-REGISTRATION.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt))
